<?php
require_once __DIR__.'/includes/online_quiz.php';require_login();$user=current_user();
try{$quiz=oq_require((int)($_GET['id']??0),$user);if(oq_owner($quiz,$user)){header('Location: online_quiz_monitor?id='.$quiz['id']);exit;}
    $count=(int)oq_query('SELECT COUNT(*) FROM online_quiz_questions WHERE quiz_id=?',[$quiz['id']])->fetchColumn();
    $attempts=oq_query('SELECT id,attempt_number,status FROM online_quiz_attempts WHERE quiz_id=? AND student_id=? ORDER BY id DESC',[$quiz['id'],$user['id']])->fetchAll();
}catch(Throwable $e){http_response_code(404);exit('Quiz not available.');}
require_once __DIR__.'/partials/online_quiz_shell.php';$hasWriting=boolval($attempts&&$attempts[0]['status']==='writing');oq_page_begin($quiz['title'],$quiz['course_code'].' — '.$quiz['course_title'],$user);
?>
<div class="oq-columns"><section class="oq-card oq-start-card"><h2><?php echo $hasWriting?'Resume your attempt':'Before you start'; ?></h2><p class="oq-prose"><?php echo h($quiz['instructions']); ?></p>
<?php if($quiz['settings']['secure']): ?><div class="oq-secure-checklist" aria-label="Secure quiz guidance"><section><i class="bi bi-wifi" aria-hidden="true"></i><div><h3>Network</h3><ul><li>Refresh and reconnect are supported.</li><li>Network loss is not a violation; <?php echo $hasWriting?'the':'once started, the'; ?> server timer continues.</li></ul></div></section><section><i class="bi bi-shield-check" aria-hidden="true"></i><div><h3>Secure test</h3><ul><li>Stay in fullscreen where supported and do not leave the quiz tab or app.</li><li>Do not use split-screen or copy and share questions.</li><li>Questions are watermarked; screenshots cannot be technically prevented.</li></ul></div></section><section><i class="bi bi-exclamation-circle" aria-hidden="true"></i><div><h3>Integrity</h3><ul><li>Confirmed violations trigger a 2-minute lockout.</li><li>Three violations flag the attempt for lecturer review, not an automatic zero.</li></ul></div></section></div><label class="oq-check"><input id="oq-ack" type="checkbox"> I have read and understand these rules.</label><?php else: ?><div class="oq-tip">Refresh and reconnect are supported, and unsent answers are buffered on this device. <?php echo $hasWriting?'The':'Once started, the'; ?> server timer continues; only answers received before expiry can be accepted.</div><?php endif; ?>
<div class="oq-toolbar"><button class="btn primary" id="oq-start"><?php echo $hasWriting?'Resume attempt':($quiz['settings']['secure']?'Start secure quiz':'Start Quiz'); ?></button><a href="assignment_tests?category=quiz" class="btn secondary">Back to quizzes</a></div>
<?php foreach($attempts as $a): ?><p><a href="<?php echo $a['status']==='writing'?'online_quiz_take.php':'online_quiz_result'; ?>?id=<?php echo (int)$a['id']; ?>">Attempt <?php echo (int)$a['attempt_number']; ?> · <?php echo h($a['status']); ?></a></p><?php endforeach; ?></section>
<aside class="oq-card"><h2>Quiz Summary</h2><dl class="oq-facts"><?php foreach(['Questions'=>$count,'Duration'=>$quiz['duration_minutes'].' minutes','Attempts'=>$quiz['attempts_allowed'],'Opens (WAT)'=>$quiz['opens_at'],'Closes (WAT)'=>$quiz['closes_at'],'Secure Test'=>$quiz['settings']['secure']?'Enabled':'Disabled','Pass mark'=>$quiz['expose_pass_mark']?$quiz['pass_percent'].'%':'Not displayed','Results'=>str_replace('_',' ',$quiz['settings']['result_release']),'Correct answers'=>str_replace('_',' ',$quiz['settings']['answer_release'])] as $k=>$v): ?><div><dt><?php echo h($k); ?></dt><dd><?php echo h((string)$v); ?></dd></div><?php endforeach; ?></dl></aside></div>
<?php oq_bootstrap(['quiz_id'=>(int)$quiz['id'],'resume'=>$hasWriting]);oq_page_end('online-quiz-start.js'); ?>
